let coepCredentialless = false

if (typeof window === "undefined") {
  self.addEventListener("install", () => self.skipWaiting())
  self.addEventListener("activate", (event) => {
    event.waitUntil(self.clients.claim())
  })

  self.addEventListener("message", (event) => {
    if (!event.data) {
      return
    }

    if (event.data.type === "deregister") {
      void self.registration
        .unregister()
        .then(() => self.clients.matchAll())
        .then((clients) => {
          clients.forEach((client) => {
            client.navigate(client.url)
          })
        })
      return
    }

    if (event.data.type === "coepCredentialless") {
      coepCredentialless = Boolean(event.data.value)
    }
  })

  self.addEventListener("fetch", (event) => {
    const request = event.request
    const url = new URL(request.url)

    if (url.pathname.startsWith("/cdn-cgi/")) {
      return
    }

    if (request.cache === "only-if-cached" && request.mode !== "same-origin") {
      return
    }

    const proxiedRequest = coepCredentialless && request.mode === "no-cors"
      ? new Request(request, { credentials: "omit" })
      : request

    event.respondWith((async () => {
      try {
        const response = await fetch(proxiedRequest)

        if (response.status === 0) {
          return response
        }

        const headers = new Headers(response.headers)
        headers.set("Cross-Origin-Embedder-Policy", coepCredentialless ? "credentialless" : "require-corp")

        if (!coepCredentialless) {
          headers.set("Cross-Origin-Resource-Policy", "cross-origin")
        }

        headers.set("Cross-Origin-Opener-Policy", "same-origin")

        if (response.status === 204 || response.status === 205 || response.status === 304 || response.body === null) {
          return new Response(null, {
            status: response.status,
            statusText: response.statusText,
            headers,
          })
        }

        return new Response(response.body, {
          status: response.status,
          statusText: response.statusText,
          headers,
        })
      } catch (error) {
        console.error(error)
        return new Response(null, {
          status: 503,
          statusText: "Service Unavailable",
        })
      }
    })())
  })
} else {
  const reloadState = window.sessionStorage.getItem("coiReloadedBySelf")
  window.sessionStorage.removeItem("coiReloadedBySelf")

  const didDegrade = reloadState === "coepdegrade"
  const settings = {
    shouldRegister: () => !reloadState,
    shouldDeregister: () => false,
    coepCredentialless: () => true,
    coepDegrade: () => true,
    doReload: () => window.location.reload(),
    quiet: false,
    ...window.coi,
  }

  const hasController = navigator.serviceWorker && navigator.serviceWorker.controller
  if (hasController && !window.crossOriginIsolated) {
    window.sessionStorage.setItem("coiCoepHasFailed", "true")
  }

  const hasFailed = window.sessionStorage.getItem("coiCoepHasFailed")

  if (hasController) {
    const shouldDegrade = settings.coepDegrade() && !(didDegrade || window.crossOriginIsolated)
    navigator.serviceWorker.controller.postMessage({
      type: "coepCredentialless",
      value: !(shouldDegrade || hasFailed && settings.coepDegrade()) && settings.coepCredentialless(),
    })

    if (shouldDegrade) {
      if (!settings.quiet) {
        console.log("Reloading page to degrade COEP.")
      }
      window.sessionStorage.setItem("coiReloadedBySelf", "coepdegrade")
      settings.doReload("coepdegrade")
    }

    if (settings.shouldDeregister()) {
      navigator.serviceWorker.controller.postMessage({ type: "deregister" })
    }
  }

  if (window.crossOriginIsolated !== true && settings.shouldRegister()) {
    if (window.isSecureContext) {
      if (navigator.serviceWorker) {
        navigator.serviceWorker.register(window.document.currentScript.src).then((registration) => {
          if (!settings.quiet) {
            console.log("COOP/COEP Service Worker registered", registration.scope)
          }

          registration.addEventListener("updatefound", () => {
            if (!settings.quiet) {
              console.log("Reloading page to make use of updated COOP/COEP Service Worker.")
            }
            window.sessionStorage.setItem("coiReloadedBySelf", "updatefound")
            settings.doReload()
          })

          if (registration.active && !navigator.serviceWorker.controller) {
            if (!settings.quiet) {
              console.log("Reloading page to make use of updated COOP/COEP Service Worker.")
            }
            window.sessionStorage.setItem("coiReloadedBySelf", "notcontrolling")
            settings.doReload()
          }
        }, (error) => {
          if (!settings.quiet) {
            console.error("COOP/COEP Service Worker failed to register:", error)
          }
        })
      } else if (!settings.quiet) {
        console.error("COOP/COEP Service Worker not registered, perhaps due to private mode.")
      }
    } else if (!settings.quiet) {
      console.log("COOP/COEP Service Worker not registered, a secure context is required.")
    }
  }
}
